defense.vulnerable_config:
-- Check linked servers and their credentials:
SELECT name, product, provider, data_source FROM sys.servers WHERE is_linked = 1;
SELECT s.name, l.remote_name, l.uses_self_credential
FROM sys.servers s JOIN sys.linked_logins l ON s.server_id = l.server_id;
-- uses_self_credential = 0 AND remote_name = 'sa' → sysadmin link = CRITICAL

-- xp_cmdshell enabled:
SELECT value_in_use FROM sys.configurations WHERE name = 'xp_cmdshell';
-- 1 = enabled = OS command execution possible

defense.secure_config:
-- Remove unnecessary linked servers:
EXEC sp_dropserver 'LINKED_SERVER_NAME', 'droplogins';

-- Disable xp_cmdshell:
EXEC sp_configure 'show advanced options', 1; RECONFIGURE;
EXEC sp_configure 'xp_cmdshell', 0; RECONFIGURE;

-- Audit linked server access:
CREATE SERVER AUDIT LinkedServerAudit TO FILE (FILEPATH = 'C:\SQLAudit\');
CREATE SERVER AUDIT SPECIFICATION LinkedServerSpec
FOR SERVER AUDIT LinkedServerAudit
ADD (LINKED_SERVER_ACCESS_GROUP);
ALTER SERVER AUDIT SPECIFICATION LinkedServerSpec WITH (STATE = ON);
ALTER SERVER AUDIT LinkedServerAudit WITH (STATE = ON);

